export type ReturnFixtureCase = "saved" | "negative" | "unknown_fee" | "short_maturity" | "on_demand" | "unknown_currency";
export function canonicalProjection(kind: ReturnFixtureCase, request: InvestorProjectionRequest, fingerprint = "a".repeat(64)): InvestorReturnProjection {
  const key = request.investment_amount === 25000 ? "stake_25000" : kind === "on_demand" ? `on_demand_${request.exit_month}` : kind;
  const stored = canonicalCases[key] ?? canonicalCases.saved;
  const encoded = stored as { template?: string; changes?: Record<string, unknown> };
  const raw = encoded.template ? { ...(canonicalCases[encoded.template] as Record<string, unknown>), ...encoded.changes } : stored;
  const value = JSON.parse(JSON.stringify(raw)) as InvestorReturnProjection & { pricing_fingerprint?: string };
  for (const point of [value.selected_exit, value.full_term, ...value.payoff_curve]) if (point && !point.assumptions) point.assumptions = [...value.assumptions];
  delete value.pricing_fingerprint;
  value.source = { kind: "published_listing", id: "CP-DOCUMENT-QA", budget_revision: 1, terms_version: 4, updated_at: "2026-11-12T18:00:00Z", fingerprint };
  value.request = { ...request };
  if (value.payoff_curve_status === "complete") value.selected_exit = value.payoff_curve.find(point => point.month === request.exit_month) ?? value.selected_exit;
  return value;
}
